    secondaryRemove: (kw, count, target, diff) => `Текущият брой на вторичната ключова дума "${kw}" е ${count}, но трябва да бъде ${target}, така че моля премахнете ${diff} от статията. Не премахвайте вторичната ключова дума от заглавия H2 или H3, ако се използва там.`
  }
};

const templates = PROMPT_TEMPLATES[targetSource] || PROMPT_TEMPLATES.EN;

const totalWords = pageText.split(/\s+/).filter(w => w.length > 0).length;
const bodyText = pageText.replace(/^#\s+.+\n/, '');
const words = bodyText.toLowerCase().replace(/[^\p{L}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 0);

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const countKW = kw => kw
  ? (pageText.toLowerCase().match(new RegExp(esc(kw), 'g')) || []).length
  : 0;

const coreKWCount = countKW(coreKeyword);
const coreKWPercentage = totalWords > 0 ? (coreKWCount / totalWords) * 100 : 0;

const h2Lines = [...pageText.matchAll(/^##\s+(.+)$/gm)].map(m => m[1].toLowerCase());
const h3Lines = [...pageText.matchAll(/^###\s+(.+)$/gm)].map(m => m[1].toLowerCase());
const allHeadings = [...h2Lines, ...h3Lines];

const secondaryStats = secondaryKeywords.map(kw => {
  const count = countKW(kw);
  return {
    keyword: kw,
    count,
    percentage: totalWords > 0 ? (count / totalWords) * 100 : 0,
    inHeading: allHeadings.some(h => h.includes(kw))
  };
});

let prompts = [];

if (coreKeyword && coreKWPercentage < 0.55) {
  const targetCount = Math.ceil(totalWords * 0.0055);
  const diff = targetCount - coreKWCount;
  if (diff > 0) prompts.push(templates.coreInject(coreKeyword, coreKWCount, targetCount, diff));
} else if (coreKeyword && coreKWPercentage > 1.3) {
  const targetCount = Math.ceil(totalWords * 0.01);
  const diff = coreKWCount - targetCount;
  if (diff > 0) prompts.push(templates.coreRemove(coreKeyword, coreKWCount, targetCount, diff));
}

secondaryStats.forEach(s => {
  if (s.percentage < 0.2) {
    const targetCount = Math.ceil(totalWords * 0.002);
    const diff = targetCount - s.count;
    if (diff > 0) prompts.push(templates.secondaryInject(s.keyword, s.count, targetCount, diff));
  } else if (s.percentage > 0.4) {
    const targetCount = Math.ceil(totalWords * 0.004);
    const diff = s.count - targetCount;
    if (diff > 0) prompts.push(templates.secondaryRemove(s.keyword, s.count, targetCount, diff));
  }
});

const coreKWinH1 = coreKeyword ? title.toLowerCase().includes(coreKeyword) : false;
const coreKWinH2 = coreKeyword ? h2Lines.some(h => h.includes(coreKeyword)) : false;
// A 500-700 word page is shorter than an article, so the opening and closing
// windows are 60 words rather than 100.
const first60text = words.slice(0, 60).join(' ');
const last60text = words.slice(-60).join(' ');
const coreKWFirst60 = coreKeyword ? first60text.includes(coreKeyword) : false;
const coreKWLast60 = coreKeyword ? last60text.includes(coreKeyword) : false;
const anySecondaryKWinH2orH3 = secondaryStats.some(s => s.inHeading);

const lines = pageText.split('\n');
let listsCount = 0;
let inList = false;
for (const line of lines) {
  const isListItem = /^\s*[-*+]\s|^\s*\d+\.\s/.test(line);
  if (isListItem && !inList) {
    listsCount++;
    inList = true;
  } else if (!isListItem && line.trim()) {
    inList = false;
  }
}

return [{
  json: {
    totalWords,
    coreKeyword,
    coreKWCount,
    coreKWPercentage: +coreKWPercentage.toFixed(2),
    coreKWinH1,
    coreKWinH2,
    coreKWFirst60,
    coreKWLast60,
    secondaryKeywords: secondaryStats.map(s => ({ ...s, percentage: +s.percentage.toFixed(2) })),
    anySecondaryKWinH2orH3,
    h2Count: h2Lines.length,
    listsCount,
    prompts
  }
}];
